 * Form lifecycle modeled as a discriminated union.
 *
 * States:
 *  - editing:    user is typing; values + per-field errors present
 *  - submitting: request in flight; only values (errors are unreachable)
 *  - succeeded:  terminal for this submission; carries the server result
 *  - failed:     submission rejected; values preserved for retry, attempt count kept
 */

export type Values = Record<string, unknown>;

export interface SuccessResult {
  id: string;
  message: string;
}

export type FormState =
  | { status: 'editing'; values: Values; errors: Partial<Record<string, string>> }
  | { status: 'submitting'; values: Values }
  | { status: 'succeeded'; result: SuccessResult }
  | { status: 'failed'; values: Values; error: string; attempt: number };

export type FormEvent =
  /** User changed a field. Only legal while editing. */
  | { type: 'CHANGE'; field: string; value: unknown }
  /** User pressed submit. Legal from editing or failed (retry). */
  | { type: 'SUBMIT' }
  /** Server accepted the in-flight submission. Only legal while submitting. */
  | { type: 'RESOLVE'; result: SuccessResult }
  /** Server rejected the in-flight submission. Only legal while submitting. */
  | { type: 'REJECT'; error: string }
  /** User resubmits after failure. Illegal unless failed. */
  | { type: 'RETRY' }
  /** User goes back to editing after success. Only legal from succeeded. */
  | { type: 'EDIT_AGAIN' };

/** Pure: returns a new state object on every handled transition, never mutates. */
export function transition(state: FormState, event: FormEvent): FormState {
  switch (event.type) {
    case 'CHANGE': {
      if (state.status !== 'editing') return state; // CHANGE while submitting/failed/succeeded: ignored
      const { [event.field]: _ignored, ...rest } = state.errors;
      return {
        status: 'editing',
        values: { ...state.values, [event.field]: event.value },
        errors: { ...rest },
      };
    }

    case 'SUBMIT': {
      if (state.status !== 'editing' && state.status !== 'failed') return state;
      // Preserve attempt count across repeated failures; first submission is attempt 1.
      const attempt = state.status === 'failed' ? state.attempt + 1 : 1;
      return { status: 'submitting', values: snapshot(state.values) };
    }

    case 'RESOLVE':
      if (state.status !== 'submitting') return state;
      return { status: 'succeeded', result: event.result };

    case 'REJECT':
      if (state.status !== 'submitting') return state;
      return {
        status: 'failed',
        values: state.values,
        error: event.error,
        attempt: 1,
      };

    case 'RETRY':
      if (state.status !== 'failed') return state; // RETRY while editing: ignored
      return { status: 'submitting', values: snapshot(state.values) };

    case 'EDIT_AGAIN':
      if (state.status !== 'succeeded') return state;
      return { status: 'editing', values: {}, errors: {} };

    default: {
      // Exhaustiveness guard: if a new variant is added to FormEvent,
      // `event` here is that variant and this assignment fails to compile.
      const _exhaustive: never = event;
      return _exhaustive;
    }
  }
}

function snapshot(values: Values): Values {
  return { ...values };
}
