result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/ts-form-state/src/state.test.ts", "content": "import { describe, expect, it } from 'vitest';
import { transition, type FormState } from './state.js';

const editing: FormState = {
  status: 'editing',
  values: { email: 'a@b.c', name: 'Ada' },
  errors: { email: 'required-ish' },
};

const submitting: FormState = { status: 'submitting', values: editing.values };

const succeeded: FormState = {
  status: 'succeeded',
  result: { id: 'f-1', message: 'created' },
};

const failed: FormState = {
  status: 'failed',
  values: editing.values,
  error: '502 bad gateway',
  attempt: 1,
};

describe('CHANGE', () => {
  it('updates the field and drops that field error while editing', () => {
    const next = transition(editing, { type: 'CHANGE', field: 'email', value: 'x@y.z' });
    expect(next).toEqual({
      status: 'editing',
      values: { email: 'x@y.z', name: 'Ada' },
      errors: {},
    });
    expect(next).not.toBe(editing); // pure: new object
  });

  it('is ignored while submitting (illegal pair)', () => {
    expect(transition(submitting, { type: 'CHANGE', field: 'email', value: 'z' })).toBe(submitting);
  });

  it('is ignored when failed', () => {
    expect(transition(failed, { type: 'CHANGE', field: 'email', value: 'z' })).toBe(failed);
  });

  it('is ignored when succeeded', () => {
    expect(transition(succeeded, { type: 'CHANGE', field: 'email', value: 'z' })).toBe(succeeded);
  });
});

describe('SUBMIT', () => {
  it('moves editing -> submitting with a snapshot of the values', () => {
    const next = transition(editing, { type: 'SUBMIT' });
    expect(next).toEqual({ status: 'submitting', values: editing.values });
    expect((next as Extract<typeof next, { status: 'submitting' }>).values).not.toBe(editing.values);
  });

  it('moves failed -> submitting (resubmit)', () => {
    const next = transition(failed, { type: 'SUBMIT' });
    expect(next.status).toBe('submitting');
    if (next.status === 'submitting') expect(next.values).toEqual(editing.values);
  });

  it('is ignored when already submitting', () => {
    expect(transition(submitting, { type: 'SUBMIT' })).toBe(submitting);
  });

  it('is ignored when succeeded', () => {
    expect(transition(succeeded, { type: 'SUBMIT' })).toBe(succeeded);
  });
});

describe('RESOLVE', () => {
  it('moves submitting -> succeeded with the server result', () => {
    const result = { id: 'ok-9', message: 'done' };
    expect(transition(submitting, { type: 'RESOLVE', result })).toEqual({
      status: 'succeeded',
      result,
    });
  });

  it('is ignored while editing', () => {
    expect(
      transition(editing, { type: 'RESOLVE', result: { id: 'x', message: '' } }),
    ).toBe(editing);
  });

  it('is ignored when failed', () => {
    expect(transition(failed, { type: 'RESOLVE', result: { id: 'x', message: '' } })).toBe(failed);
  });
});

describe('REJECT', () => {
  it('moves submitting -> failed preserving the values for retry', () => {
    expect(transition(submitting, { type: 'REJECT', error: 'timeout' })).toEqual({
      status: 'failed',
      values: submitting.values,
      error: 'timeout',
      attempt: 1,
    });
  });

  it('is ignored while editing', () => {
    expect(transition(editing, { type: 'REJECT', error: 'nope' })).toBe(editing);
  });
});

describe('RETRY', () => {
  it('moves failed -> submitting', () => {
    const next = transition(failed, { type: 'RETRY' });
    expect(next.status).toBe('submitting');
    if (next.status === 'submitting') expect(next.values).toEqual(editing.values);
  });

  it('is ignored while editing (illegal pair)', () => {
    expect(transition(editing, { type: 'RETRY' })).toBe(editing);
  });

  it('is ignored while submitting', () => {
    expect(transition(submitting, { type: 'RETRY' })).toBe(submitting);
  });

  it('is ignored when succeeded', () => {
    expect(transition(succeeded, { type: 'RETRY' })).toBe(succeeded);
  });
});

describe('EDIT_AGAIN', () => {
  it('moves succeeded -> editing with fresh values and no errors', () => {
    expect(transition(succeeded, { type: 'EDIT_AGAIN' })).toEqual({
      status: 'editing',
      values: {},
      errors: {},
    });
  });

  it('is ignored while editing', () => {
    expect(transition(editing, { type: 'EDIT_AGAIN' })).toBe(editing);
  });

  it('is ignored while submitting', () => {
    expect(transition(submitting, { type: 'EDIT_AGAIN' })).toBe(submitting);
  });

  it('is ignored when failed', () => {
    expect(transition(failed, { type: 'EDIT_AGAIN' })).toBe(failed);
  });
});

describe('purity', () => {
  it('never mutates the input state', () => {
    const before = structuredClone(editing);
    transition(editing, { type: 'CHANGE', field: 'name', value: 'Grace' });
    transition(editing, { type: 'SUBMIT' });
    expect(editing).toEqual(before);
  });
});
