 * Compile-time tests. Nothing here runs assertions at runtime; the point is
 * that `npx tsc --noEmit` fails unless every @ts-expect-error below is
 * "used" — i.e., each one marks code that genuinely does not type-check.
 */
import { describe, expect, it } from 'vitest';
import type { FormEvent, FormState } from './state.js';

function narrowToSubmitting(): FormState {
  return { status: 'submitting', values: {} };
}

describe('discriminated union narrows correctly', () => {
  it('errors are unreadable on a submitting state', () => {
    const state = narrowToSubmitting();

    // The whole reason `submitting` omits `errors`: this must not compile.
    // @ts-expect-error Property 'errors' does not exist on type '{ status: "submitting"; values: Values; }'
    expect(state.errors).toBeUndefined();
  });

  it('result is unreadable on a failed state', () => {
    const state: FormState = { status: 'failed', values: {}, error: 'e', attempt: 1 };

    // @ts-expect-error Property 'result' does not exist on type '{ status: "failed"; ... }'
    expect(state.result).toBeUndefined();
  });

  it('error string is unreadable on an editing state (it has errors map instead)', () => {
    const state: FormState = { status: 'editing', values: {}, errors: {} };

    // @ts-expect-error Property 'attempt' does not exist on type '{ status: "editing"; ... }'
    expect(state.attempt).toBeUndefined();
  });

  it('a valid event typechecks fine (control case, no ts-expect-error)', () => {
    const event: FormEvent = { type: 'CHANGE', field: 'email', value: 'a@b.c' };
    expect(event.type).toBe('CHANGE');
  });
});
"})
